{"cmd":"python3 - <<'PY'
import pdfplumber, pandas as pd, json
from pathlib import Path

pdf_path=Path('/root/employees_backup.pdf')
headers=['ID','First','Last','Dept','Position','Salary','Years','Location','Score']
rows=[]

with pdfplumber.open(pdf_path) as pdf:
    for page in pdf.pages:
        table=page.extract_table()
        if not table:
            continue
        header=table[0]
        for r in table[1:]:
            if not any(r):
                continue
            if [c.strip() if c else '' for c in r] == [c.strip() if c else '' for c in header]:
                continue
            r=(r+[None]*len(headers))[:len(headers)]
            rows.append(r)

df_old=pd.DataFrame(rows, columns=headers)

# clean old data types
# strip whitespace
for col in ['ID','First','Last','Dept','Position','Location']:
    df_old[col]=df_old[col].astype(str).str.strip()

# Salary: remove commas, convert to int
# some rows might have empty; coerce
salary = df_old['Salary'].astype(str).str.replace(',', '', regex=False).str.strip()

def to_int(val):
    try:
        if val == '' or val.lower() == 'none' or val == 'nan':
            return None
        return int(float(val))
    except Exception:
        return None

def to_float(val):
    try:
        if val == '' or val.lower() == 'none' or val == 'nan':
            return None
        return float(val)
    except Exception:
        return None


df_old['Salary']=salary.map(to_int)

df_old['Years']=df_old['Years'].astype(str).str.strip().map(to_int)

df_old['Score']=df_old['Score'].astype(str).str.strip().map(to_float)

# load new
xlsx_path=Path('/root/employees_current.xlsx')
df_new=pd.read_excel(xlsx_path)

# ensure types for new
for col in ['ID','First','Last','Dept','Position','Location']:
    df_new[col]=df_new[col].astype(str).str.strip()

# numeric
# ensure int for Salary/Years; float for Score
# note: pandas may use numpy types

# build dicts by ID
old_by_id = {row['ID']: row for _, row in df_old.iterrows()}
new_by_id = {row['ID']: row for _, row in df_new.iterrows()}

old_ids=set(old_by_id)
new_ids=set(new_by_id)

deleted_ids=sorted(old_ids - new_ids)

fields=headers[1:]  # exclude ID
modified=[]

for emp_id in sorted(old_ids & new_ids):
    old_row=old_by_id[emp_id]
    new_row=new_by_id[emp_id]
    for field in fields:
        old_val=old_row[field]
        new_val=new_row[field]
        # Normalize numeric types and NaN
        if pd.isna(old_val):
            old_val=None
        if pd.isna(new_val):
            new_val=None
        # cast numeric fields to python numbers
        if field in ['Salary','Years']:
            if old_val is not None:
                try:
                    old_val=int(old_val)
                except Exception:
                    pass
            if new_val is not None:
                try:
                    new_val=int(new_val)
                except Exception:
                    pass
        elif field in ['Score']:
            if old_val is not None:
                try:
                    old_val=float(old_val)
                except Exception:
                    pass
            if new_val is not None:
                try:
                    new_val=float(new_val)
                except Exception:
                    pass
        else:
            # ensure strings
            if old_val is not None:
                old_val=str(old_val)
            if new_val is not None:
                new_val=str(new_val)
        if old_val != new_val:
            modified.append({
                'id': emp_id,
                'field': field,
                'old_value': old_val,
                'new_value': new_val
            })

# sort modified by id then field
modified.sort(key=lambda x: (x['id'], x['field']))

report={'deleted_employees': deleted_ids, 'modified_employees': modified}

out_path=Path('/root/diff_report.json')
with out_path.open('w') as f:
    json.dump(report, f, indent=2)

print('deleted', len(deleted_ids), 'modified', len(modified))
print('wrote', out_path)
PY"}
